#!/usr/bin/env python3
"""
Round 158b (culprits), 4 October 2026. Needs round 157b.

Closest zooms show the real photograph, sharp, lightly graded.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 158b (4 October)\n\nNeeds round 157b. No tiles patch. No app.js?v= bump.\n\n- Owner: at the closest zooms only, back to the normal satellite picture,\n  keeping some of the woodland look without blurring the detail; all else\n  good.\n- New layer outline-wood-photo (woodphoto://, woodGradePixels): Esri World\n  Imagery (as the Satellite basemap uses close in), each pixel moved 35% of\n  the way to its woodland colour (WOOD.photoGrade), colour only: no blur, no\n  strokes. Fades in from zoom 15.5 to 16.5 (WOOD.photoFrom / photoFull); the\n  painting stops at 17. The light, mist and sea tint still lie over it.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round158b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 157b" not in h.read_text(encoding="utf-8"):
        sys.exit("round158b: round 157b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round158b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round158b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round158b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
